// Simple bold tag formatter helper
function renderFormattedText(text: string) {
  if (!text) return null;
  const parts = text.split('**');
  return (
    <>
      {parts.map((part, i) => (
        i % 2 === 1 ? <strong key={i} className="text-white font-semibold">{part}</strong> : part
      ))}
    </>
  );
}

